(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+wx)*0.01+t*0.15)*8 + Math.cos((y+wy)*0.012-t*0.1)*6;
  wy += Math.cos((y+wy)*0.01-t*0.12)*8 + Math.sin((x+wx)*0.011+t*0.18)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100+Math.cos(t*0.3)*30, 80+Math.cos(t*0.4)*50+Math.sin(t*0.7)*20, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100+Math.sin(t*0.25)*40, 160+Math.sin(t*0.7)*50+Math.cos(t*0.35)*25, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140+Math.cos(t*0.15+1)*50, 120+Math.cos(t*0.5+1)*90+Math.sin(t*0.4)*30, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80+Math.sin(t*0.6)*25, 180+Math.sin(t*0.6+3)*60+Math.cos(t*0.9)*20, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90+Math.cos(t*0.2+2)*35, 60+Math.cos(t*0.9+2)*70+Math.sin(t*0.5)*25, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120+Math.sin(t*0.18)*40, 200+Math.sin(t*0.55)*80+Math.cos(t*0.3)*30, 0.09, 1.9],
    [60+Math.sin(t*0.45+3)*70+Math.cos(t*0.22)*35, 40+Math.cos(t*0.65+2)*55+Math.sin(t*0.8)*20, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60+Math.sin(t*0.28+3)*30, 220+Math.sin(t*0.45+4)*45+Math.cos(t*0.6)*25, 0.075, 1.8]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS += Math.cos(d*f*0.5-t*sp*0.3+2.8);
  }
  const act=aS/8, inh=iS/8, mod=mS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.055+t*0.7)*Math.sin(sy*0.045-t*0.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*6+t*0.8)*0.15+Math.cos(dist*0.065+ang*2-t*2.1)*0.1;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.2)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3
    +Math.tanh(Math.sin(sx*0.08+t*0.3)*Math.cos(sy*0.09-t*0.4))*0.1;
  const blend = reaction*0.65+cell*0.2+mod*0.15, v=blend*0.5+0.5;
  const pal = [[5,12,55],[10,55,95],[15,110,120],[25,165,130],[160,190,80],[220,175,60],[215,130,65],[195,80,70],[150,45,65],[90,25,70],[45,15,60],[5,12,55]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const shimmer=1.0+Math.sin(ang*5+t*3)*0.03*Math.abs(reaction);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge*shimmer)|0
  ];
}
